#!/bin/sh
# Print the static allowlist: every git-tracked file in the repo except the
# server code, docs and git housekeeping. Output is sorted and stable.
# Usage: scripts/gen-allowlist.sh [repo-root]
set -eu
root="${1:-$(git rev-parse --show-toplevel)}"
cat <<'HDR'
# Generated by `make allowlist` (scripts/gen-allowlist.sh) from `git ls-files`.
# One path per line, relative to RUYI_STATIC_DIR. Do not edit by hand:
# `go test ./...` fails if this file drifts from git.
HDR
git -C "$root" ls-files \
  | grep -v -E '^(server/|docs/|\.gitignore$|\.github/)' \
  | LC_ALL=C sort
